def transform(grid):
    """Recolor large solid monochrome rectangles to 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = set()
    # For each vertical span, find horizontal runs that are the same color
    # in every row of the span. Any run at least 5x5 is a target rectangle.
    for top in range(h):
        for bottom in range(top + 4, h):
            c = 0
            while c < w:
                color = grid[top][c]
                end = c + 1
                while end < w and all(grid[r][end] == color for r in range(top, bottom + 1)) and all(grid[r][c] == color for r in range(top, bottom + 1)):
                    end += 1
                # If the first column of the run isn't uniform (or a mismatch
                # was encountered), advance past this column.
                if not all(grid[r][c] == color for r in range(top, bottom + 1)):
                    c += 1
                    continue
                # Extend across all columns uniformly matching this color.
                while end < w and all(grid[r][end] == color for r in range(top, bottom + 1)):
                    end += 1
                if end - c >= 5:
                    for r in range(top, bottom + 1):
                        for x in range(c, end):
                            marked.add((r, x))
                c = end
    for r, c in marked:
        out[r][c] = 4
    return out

